import {ActivityIndicator, FlatList, View} from 'react-native';
import HeaderCM from '../../components/Header/HeaderCM';
import {useRoute} from '@react-navigation/native';
import {GroupTaskList, ITask} from '../board/store/interface';
import TaskDetailItem from './components/task-detail-item';
import {useBoardService, useUserService} from '../../../hooks/apiHooks/useAPI';
import {useEffect, useState} from 'react';
import Toast from 'react-native-toast-message';
import {SafeAreaView} from 'react-native-safe-area-context';
import {Color} from '../../../constants';
import {Icon, Menu, MenuItem} from '@ui-kitten/components';
import {useUserStore} from '../../../zutand/user-store';
import useBoardStore from '../board/store';
import BottomSheetCM from '../../components/BottomSheet';
import TextCM from '../../components/Text';
import {useTranslation} from 'react-i18next';
const TaskScreen = () => {
  const {t} = useTranslation();
  const route = useRoute<any>();
  const taskSelectId = route?.params?.taskId as string;
  const [taskSelect, setTaskSelect] = useState<ITask | null>(null);
  const [groupTaskList, setGroupTaskList] = useState<GroupTaskList[]>([]);
  const {setListUser, setListGroupUser} = useUserStore();
  const BoardServices = useBoardService();
  const UserServices = useUserService();
  const {setGroupTaskList: setGroupTaskListStore} = useBoardStore();
  const [isVisible, setIsVisible] = useState(false);
  const [viewType, setViewType] = useState<'table' | 'list' | 'calendar'>(
    'table',
  );

  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getListTaskById();
  }, []);
  const changeSelectTab = async (tab: 'table' | 'list' | 'calendar') => {
    if (tab !== viewType) {
      setViewType(tab);
      setIsVisible(false);
    }
  };
  const selectedGroupTask = taskSelectId
    ? groupTaskList.find(item => item.listTaskId === taskSelectId)
    : undefined;

  const renderAction = () => {
    return (
      <Menu>
        <MenuItem
          key={'tableView'}
          title={props => <TextCM {...props}>{t('board.type-board')}</TextCM>}
          onPress={() => changeSelectTab('table')}
          accessoryRight={
            viewType == 'table' ? <Icon name="checkmark" /> : undefined
          }
        />
        <MenuItem
          key={'listView'}
          title={props => <TextCM {...props}>{t('board.type-list')}</TextCM>}
          onPress={() => changeSelectTab('list')}
          accessoryRight={
            viewType == 'list' ? <Icon name="checkmark" /> : undefined
          }
        />
        <MenuItem
          key={'calendarView'}
          title={props => (
            <TextCM {...props}>{t('board.type-calendar')}</TextCM>
          )}
          onPress={() => changeSelectTab('calendar')}
          accessoryRight={
            viewType == 'calendar' ? <Icon name="checkmark" /> : undefined
          }
        />
      </Menu>
    );
  };
  const getListTaskById = async () => {
    try {
      setLoading(true);
      const data = (await BoardServices.getTaskById(taskSelectId)) as ITask;
      if (data) {
        setTaskSelect(data);
        const listGroupId = data?.assignGroupList?.map(group => group?.groupId);
        const sorted = data.groupTaskList?.sort(
          (a: GroupTaskList, b: GroupTaskList) => {
            const orderA = JSON.parse(a.attr).order;
            const orderB = JSON.parse(b.attr).order;
            return orderA - orderB;
          },
        );
        setGroupTaskList(sorted);
        setGroupTaskListStore(sorted);
        const listUserId = data.assignTaskList.map(item => item.userId);
        const bodyGetUser = {
          resourceIds: listUserId,
        };
        const params = {
          page: 0,
          size: 10000,
          role: true,
        };
        const [dataUser, dataGroupList] = await Promise.all([
          UserServices.getUser(bodyGetUser, params),
          listGroupId?.length > 0 && UserServices.findListGroup(listGroupId),
        ]);
        if (dataUser) {
          setListUser(dataUser.data);
        }
        if (dataGroupList) {
          setListGroupUser(dataGroupList);
        }
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('board.task-not-found'),
        });
      }
    } catch (error) {
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <View style={{flex: 1, justifyContent: 'center', alignItems: 'center'}}>
        <ActivityIndicator size="large" color={Color.BgPrimary} />
      </View>
    );
  }

  return (
    <SafeAreaView edges={['bottom']} style={{flex: 1, backgroundColor: '#fff'}}>
      <HeaderCM
        alignment="start"
        title={taskSelect?.name}
        // renderContentRight={() => (
        //   <View style={{flexDirection: 'row', gap: 10}}>
        //     <Pressable onPress={() => setIsVisible(true)}>
        //       <Icon fill={'#fff'} name="eye-outline" width={24} height={24} />
        //     </Pressable>
        //   </View>
        // )}
      />
      {taskSelect &&
        (viewType === 'table' ? (
          <FlatList
            pagingEnabled={true}
            horizontal
            showsHorizontalScrollIndicator={false}
            showsVerticalScrollIndicator={false}
            data={[
              ...groupTaskList,
              {
                name: 'add',
                type: 'add',
                attr: JSON.stringify({
                  color: Color.colorBorder,
                }),
              } as GroupTaskList,
            ]}
            renderItem={({item}) => (
              <TaskDetailItem
                setGroupTaskList={setGroupTaskList}
                taskSelectId={taskSelectId}
                groupTaskList={item}
                viewType="table"
              />
            )}
          />
        ) : viewType === 'list' ? (
          <TaskDetailItem
            setGroupTaskList={setGroupTaskList}
            taskSelectId={taskSelectId}
            viewType="list"
          />
        ) : (
          <TaskDetailItem
            groupTaskList={selectedGroupTask}
            setGroupTaskList={setGroupTaskList}
            taskSelectId={taskSelectId}
            viewType="calendar"
          />
        ))}

      <BottomSheetCM
        title={t('board.type-view')}
        onClose={() => setIsVisible(false)}
        isVisible={isVisible}
        renderContent={renderAction()}
      />
    </SafeAreaView>
  );
};

export default TaskScreen;
