import {forwardRef, useRef, useState} from 'react';
import {
  Animated,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  View,
} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import {HEADER_MAX_HEIGHT, HEADER_SCROLL_DISTANCE} from './styleHeaderScroll';
import styles from './styleHeaderScroll';
import {Divider, Icon, Menu, MenuItem} from '@ui-kitten/components';
import {useNavigation} from '@react-navigation/native';
import TextCM from '../Text';
import ModalFullScreen from '../ModalFullScreen';
import HeaderCM from './HeaderCM';
import BottomSheetCM from '../BottomSheet';
import {useTranslation} from 'react-i18next';

type Props = {
  title?: string;
  renderContent?: any;
  srcImage?: any;
  handleBackPress?: () => void;
};

const HeaderScrollView = forwardRef(
  (
    {title = 'quangnh39', renderContent, srcImage, handleBackPress}: Props,
    ref,
  ) => {
    const {t} = useTranslation();
    const navigation = useNavigation();
    const scrollY = useRef(new Animated.Value(0)).current; // our animated value
    const [openModal, setOpenModal] = useState(false);
    const [isVisible, setIsVisible] = useState(false);
    const [selectColor, setSelectColor] = useState<string | undefined>();

    const COLORS = [
      '#fff',
      '#33FF57',
      '#3357FF',
      '#F39C12',
      '#8E44AD',
      '#2ECC71',
      '#E74C3C',
      '#1ABC9C',
      '#34495E',
      '#FFC300',
    ];

    // our header y-axis animated from 0 to HEADER_SCROLL_DISTANCE,
    // we move our element for -HEADER_SCROLL_DISTANCE at the same time.
    const headerTranslateY = scrollY.interpolate({
      inputRange: [0, HEADER_SCROLL_DISTANCE],
      outputRange: [0, -HEADER_SCROLL_DISTANCE],
      extrapolate: 'clamp',
    });

    // our opacity animated from 0 to 1 and our opacity will be 0
    const imageOpacity = scrollY.interpolate({
      inputRange: [0, HEADER_SCROLL_DISTANCE / 2, HEADER_SCROLL_DISTANCE],
      outputRange: [1, 1, 0],
      extrapolate: 'clamp',
    });
    const imageTranslateY = scrollY.interpolate({
      inputRange: [0, HEADER_SCROLL_DISTANCE],
      outputRange: [0, 100],
      extrapolate: 'clamp',
    });

    // change header title size from 1 to 0.9
    const titleScale = scrollY.interpolate({
      inputRange: [0, HEADER_SCROLL_DISTANCE / 2, HEADER_SCROLL_DISTANCE],
      outputRange: [1, 1, 0.9],
      extrapolate: 'clamp',
    });

    const opacity = scrollY.interpolate({
      inputRange: [0, HEADER_SCROLL_DISTANCE / 2, HEADER_SCROLL_DISTANCE],
      outputRange: [0, 0.5, 1],
      extrapolate: 'clamp',
    });
    // change header title y-axis
    const titleTranslateY = scrollY.interpolate({
      inputRange: [0, HEADER_SCROLL_DISTANCE / 2, HEADER_SCROLL_DISTANCE],
      outputRange: [0, 0, -8],
      extrapolate: 'clamp',
    });

    const handleBack = () => {
      if (handleBackPress) {
        handleBackPress();
      } else {
        navigation.goBack();
      }
    };
    const renderAction = () => {
      return (
        <Menu>
          <MenuItem
            title={props => (
              <TextCM {...props}>{t('task.choose-from-library')}</TextCM>
            )}
            onPress={() => {}}
          />
          <MenuItem
            title={props => <TextCM {...props}>{t('task.take-photo')}</TextCM>}
            onPress={() => {}}
          />
        </Menu>
      );
    };
    return (
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        style={{flex: 1, backgroundColor: '#eff3fb'}}>
        <SafeAreaView edges={['top']} style={styles.saveArea}>
          <Animated.ScrollView
            ref={ref as any}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
            contentContainerStyle={{
              paddingTop: HEADER_MAX_HEIGHT,
            }}
            scrollEventThrottle={16}
            onScroll={Animated.event(
              [{nativeEvent: {contentOffset: {y: scrollY}}}],
              {useNativeDriver: true},
            )}>
            {renderContent}
          </Animated.ScrollView>
          <Animated.View
            style={[
              styles.header,
              {transform: [{translateY: headerTranslateY}]},
            ]}>
            <View
              style={{
                height: HEADER_MAX_HEIGHT,
                overflow: 'hidden',
              }}>
              {selectColor ? (
                <Animated.View
                  style={[
                    styles.headerBackground,
                    {
                      backgroundColor: selectColor,
                      opacity: imageOpacity,
                      transform: [{translateY: imageTranslateY}],
                    },
                  ]}
                />
              ) : (
                <Animated.Image
                  style={[
                    styles.headerBackground,
                    {
                      opacity: imageOpacity,
                      transform: [{translateY: imageTranslateY}],
                    },
                  ]}
                  source={
                    srcImage || {
                      uri: 'https://media.daily.dev/image/upload/f_auto,q_auto/v1/posts/e7e602321e6ead7d05920979a037fea1?_a=AQAEuj9',
                    }
                  }
                />
              )}
            </View>
            {/* <Animated.View
              style={{
                position: 'absolute',
                bottom: 16,
                left: 16,
                opacity: imageOpacity,
                transform: [{translateY: imageTranslateY}],
                backgroundColor: 'black',
                padding: 8,
                borderRadius: 20,
              }}>
              <Pressable
                onPress={() => setOpenModal(true)}
                style={{flexDirection: 'row', alignItems: 'center', gap: 8}}>
                <Icon
                  name="image-outline"
                  height={20}
                  width={20}
                  fill="white"
                />
                <TextCM style={{color: 'white'}}>
                  {t('task.cover-photo')}
                </TextCM>
              </Pressable>
            </Animated.View> */}
          </Animated.View>

          <Animated.View
            style={[
              styles.topBar,
              {
                transform: [{scale: titleScale}, {translateY: titleTranslateY}],
              },
            ]}>
            <View
              style={{
                flexDirection: 'row',
                alignItems: 'center',
                width: '100%',
                justifyContent: 'center',
              }}>
              <Pressable
                onPress={handleBack}
                style={{
                  left: 0,
                  zIndex: 1,
                  position: 'absolute',
                }}>
                <Icon name="close" width={24} height={24} fill={'#fff'} />
              </Pressable>
              <Animated.Text
                numberOfLines={1}
                style={[styles.title, {opacity: opacity}]}>
                {title}
              </Animated.Text>
            </View>
          </Animated.View>
        </SafeAreaView>
        <ModalFullScreen
          isVisible={openModal}
          children={
            <View>
              <HeaderCM
                style={{
                  backgroundColor: '#fff',
                }}
                contentStyle={{
                  backgroundColor: '#fff',
                }}
                titleStyle={{
                  color: '#000810',
                }}
                fillIconBackLeft="#000810"
                onPressIconLeft={() => {
                  setOpenModal(false);
                }}
                title={t('task.background')}
                alignment="start"
              />
              <Divider />
              <View style={styles.colorbgctn}>
                <TextCM style={{marginBottom: 8}}>{t('CM.color')}</TextCM>

                <View style={styles.colorGrid}>
                  {COLORS.map((color, index) => (
                    <Pressable
                      key={index}
                      onPress={() => setSelectColor(color)}
                      style={[styles.colorBox, {backgroundColor: color}]}
                    />
                  ))}
                </View>
              </View>

              <View style={styles.colorbgctn}>
                <TextCM>{t('task.attachments')}</TextCM>
                <View style={{marginTop: 20}}>
                  <Pressable
                    style={styles.imgBox}
                    onPress={() => setIsVisible(true)}>
                    <Icon name="plus-outline" height={34} width={34} />
                  </Pressable>
                </View>
              </View>
            </View>
          }
        />
        <BottomSheetCM
          title={t('task.choose-file')}
          onClose={() => setIsVisible(false)}
          isVisible={isVisible}
          renderContent={renderAction()}
        />
      </KeyboardAvoidingView>
    );
  },
);

export default HeaderScrollView;
