import {Pressable, View} from 'react-native';
import TextCM from '../../../../../../components/Text';
import {AssignReviewList} from '../../../task-detail-item/helper';
import {useMemo, useState} from 'react';
import {useUserStore} from '../../../../../../../zutand/user-store';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import CustomSelectUser from '../../../../../../components/ModalSelectUser/component/user';
import {useTaskService} from '../../../../../../../hooks/apiHooks/useAPI';
import {useTranslation} from 'react-i18next';

type Props = {
  assignReviewList?: AssignReviewList[];
  taskId: string;
  handleUpdateTask: (data: AssignReviewList[]) => void;
};

const TaskReview = ({assignReviewList, taskId, handleUpdateTask}: Props) => {
  const {t} = useTranslation();
  const [openModalUser, setOpenModalUser] = useState(false);
  const {listUser} = useUserStore();
  const userReview = useMemo(() => {
    const user = listUser?.find(
      u => u.resourceId === assignReviewList?.[0]?.userId,
    );
    return user;
  }, [assignReviewList]);

  const TaskService = useTaskService();

  const handleGetdata = (data: any) => {
    delete data?.[0]?.custId;
    if (data.length) {
      handleAssignReview({
        ...data[0],
        updateByListTask: false,
        updateBySubtask: false,
      });
    } else {
      handleDeleteReview();
    }
    setOpenModalUser(false);
  };

  const handleAssignReview = async (data: any) => {
    const dataResp = await TaskService.taskReview(data);
    if (dataResp) {
      handleUpdateTask([dataResp]);
    }
  };

  const handleDeleteReview = async () => {
    const dataResp = await TaskService.deleteTaskReview(
      assignReviewList?.[0]?.id,
    );
    if (dataResp) {
      handleUpdateTask([]);
    }
  };

  return (
    <>
      <Pressable
        onPress={() => setOpenModalUser(true)}
        style={{
          alignItems: 'flex-start',
          justifyContent: 'center',
        }}>
        <TextCM>
          {userReview
            ? t('task.approver') + ': ' + userReview?.email
            : t('task.approverPlace')}
        </TextCM>
      </Pressable>

      <ModalFullScreen
        isVisible={openModalUser}
        children={
          <>
            <CustomSelectUser
              type="T"
              assignUserList={assignReviewList}
              handleUserSelect={handleGetdata}
              resourceId={taskId}
              multiple={false}
              id={assignReviewList?.[0]?.id}
              isShowHeader={true}
              onClose={() => setOpenModalUser(false)}
            />
          </>
        }
      />
    </>
  );
};

export default TaskReview;
