import {Divider} from '@ui-kitten/components';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import {useState} from 'react';
import ButtonCM from '../../../../../../components/Button';
import {FlatList, TouchableOpacity, View} from 'react-native';
import {CIRCLE_COLOR_PICKER} from '../../helper';
import TextFieldCM from '../../../../../../components/TextField';
import {useTranslation} from 'react-i18next';

type Props = {
  onClose?: () => void;
  handleSubmitData?: (data: any) => void;
};

const AddBoard = ({onClose, handleSubmitData}: Props) => {
  const {t} = useTranslation();
  const [value, setValue] = useState<string>('');
  const [color, setColor] = useState<string>(CIRCLE_COLOR_PICKER[0]);
  const [error, setError] = useState<string>('');

  return (
    <>
      <HeaderCM
        style={{
          backgroundColor: '#fff',
        }}
        contentStyle={{
          backgroundColor: '#fff',
        }}
        titleStyle={{
          color: '#000810',
        }}
        fillIconBackLeft="#000810"
        onPressIconLeft={() => {
          onClose?.();
        }}
        title={t('task.add-status')}
        alignment="start"
      />
      <Divider />

      <TextFieldCM
        containerStyle={{
          paddingVertical: 10,
          paddingHorizontal: 16,
        }}
        value={value}
        onChangeText={setValue}
        label={t('task.add-status')}
        allowFontScaling={false}
        errorMessage={error}
        onBlur={() =>
          !value?.trim() ? setError(t('task.cant-empty')) : setError('')
        }
      />

      <FlatList
        data={CIRCLE_COLOR_PICKER}
        style={{
          flex: 1,
          paddingHorizontal: 16,
        }}
        contentContainerStyle={{
          flexDirection: 'row',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: 10,
        }}
        renderItem={({item}) => (
          <TouchableOpacity
            onPress={() => setColor(item)}
            style={{
              width: 40,
              height: 40,
              borderRadius: 20,
              justifyContent: 'center',
              alignItems: 'center',
              borderWidth: color === item ? 8 : 0,
              borderColor: item,
              backgroundColor: item !== color ? item : '#fff',
            }}>
            <View />
          </TouchableOpacity>
        )}
      />

      <ButtonCM
        style={{
          marginHorizontal: 16,
        }}
        disabled={!value?.trim()}
        label={t('CM.confirm')}
        onPress={() => handleSubmitData?.({name: value?.trim(), color})}
      />
    </>
  );
};

export default AddBoard;
